import type { InjectionKey } from "vue";

/** NumberInput Root 上下文：仅用于子组件的开发期 guard 探测（Form 家族同款模式） */
export const NUMBER_INPUT_KEY: InjectionKey<true> = Symbol("tu-number-input");

export { default as NumberInput } from "./NumberInput.vue";
export { default as NumberInputInput } from "./NumberInputInput.vue";
export { default as NumberInputDecrement } from "./NumberInputDecrement.vue";
export { default as NumberInputIncrement } from "./NumberInputIncrement.vue";
export { numberOrNull } from "./utils";

/** Ark ValueChangeDetails → number|null（空串/NaN 归一 null，numberOrNull 为可单测的纯函数） */
export function numberOrNull(details: { value: string; valueAsNumber: number }): number | null {
  return details.value === "" || Number.isNaN(details.valueAsNumber) ? null : details.valueAsNumber;
}
